#!/usr/bin/env php
<?php

declare(strict_types=1);
ini_set('memory_limit', '512M');

$args = array_slice($argv,1);
$opts=[];
foreach($args as $arg) if(preg_match('/^--(before-questions|before-eligibility|after-questions|after-eligibility|json|markdown)=(.+)$/',$arg,$m))$opts[$m[1]]=$m[2];
foreach(['before-questions','before-eligibility','after-questions','after-eligibility','json','markdown'] as $key)if(!isset($opts[$key]))throw new RuntimeException('Missing --'.$key.'=PATH');
$read=static fn(string $path):array=>json_decode((string)file_get_contents($path),true,512,JSON_THROW_ON_ERROR);
$beforeQ=$read($opts['before-questions']);$beforeE=$read($opts['before-eligibility']);$afterQ=$read($opts['after-questions']);$afterE=$read($opts['after-eligibility']);
$domains=[];foreach($read(dirname(__DIR__).'/storage/taxonomy/domains.json') as $d)$domains[(string)$d['id']]=$d;
$byBoard=[];
foreach([['before',$beforeE],['after',$afterE]] as [$version,$entries])foreach($entries as $entry){if(!is_array($entry))continue;foreach(array_map('strval',(array)($entry['question_ids']??[])) as $id){$override=is_array($entry['question_mappings'][$id]??null)?$entry['question_mappings'][$id]:[];$exams=(array)($override['exam_ids']??$entry['exam_ids']??[]);$subjects=(array)($override['subject_ids']??$entry['subject_ids']??[]);$placements=(array)($override['placements']??[]);foreach($exams as $exam){$board=strtolower((string)$exam);$board=['ree'=>'registered-electrical-engineering','arch'=>'architecture'][$board]??$board;$byBoard[$version][$id][$board]=(string)($placements[$exam]['subject_id']??$placements[$board]['subject_id']??$subjects[$exam]??$subjects[$board]??'');}}}
$qAfter=[];foreach($afterQ as $q)if(is_array($q))$qAfter[(string)$q['id']]=$q;
$rows=[];
foreach($beforeQ as $old){if(!is_array($old))continue;$id=(string)($old['id']??'');$tax=(array)($old['taxonomy']??[]);$rawBoard=strtolower((string)($tax['board_id']??$old['board']??''));$board=['ree'=>'registered-electrical-engineering','arch'=>'architecture'][$rawBoard]??$rawBoard;if(!in_array($board,['let','registered-electrical-engineering','architecture'],true))continue;$domain=$domains[(string)($tax['domain_id']??'')]??null;if(!is_array($domain))continue;$target=(string)($domain['subject_id']??'');$from=(string)($byBoard['before'][$id][$board]??'');if($from===''&&$board===$rawBoard)$from=(string)($tax['subject_id']??'');$to=(string)($byBoard['after'][$id][$board]??'');if($from===''||$from===$target||$to!==$target)continue;$new=$qAfter[$id]??$old;$newTax=(array)($new['taxonomy']??[]);$rows[]=['question_id'=>$id,'board_id'=>$board,'from_subject_id'=>$from,'to_subject_id'=>$target,'taxonomy_subject_id'=>(string)($newTax['subject_id']??''),'domain_id'=>(string)($newTax['domain_id']??''),'topic_id'=>(string)($newTax['topic_id']??''),'concept_id'=>(string)($newTax['concept_id']??''),'question_stem'=>(string)($new['question']??''),'evidence'=>'Existing taxonomy domain '.$newTax['domain_id'].' resolves to destination subject '.$target.'; destination blueprint placement was validated with QuestionEligibilityService.'];}
usort($rows,static fn($a,$b)=>[$a['board_id'],$a['from_subject_id'],$a['to_subject_id'],(int)$a['question_id']]<=>[$b['board_id'],$b['from_subject_id'],$b['to_subject_id'],(int)$b['question_id']]);
$groups=[];foreach($rows as $r){$k=$r['board_id'].'|'.$r['from_subject_id'].'|'.$r['to_subject_id'];$groups[$k]=($groups[$k]??0)+1;}
$report=['report_type'=>'BATCH_694_SUBJECT_CLASSIFICATION_AUDIT','schema_version'=>1,'before_head'=>'945d968ce6ac78a97aa7574edad8b24bdc0542bb','records_reclassified'=>count($rows),'groups'=>$groups,'basis'=>'Only existing placements where the destination subject equals the existing taxonomy domain subject were changed. The exact destination board/subject/domain/topic/concept/blueprint mapping passed the production question-mapping validator. No question taxonomy identities or learner usage records were deleted.','records'=>$rows];
$json=json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n";
$lines=['# Batch 694 Subject Classification Audit','','Reconciled existing effective placements to the question’s existing taxonomy domain subject when a matching board blueprint node existed and production mapping validation passed. These were placement corrections supported by existing question provenance; they do not create new content or answer mappings.','', '**Reclassified records:** '.count($rows),'','| Board | Current subject | Correct subject | Records |','|---|---|---|---:|'];foreach($groups as $k=>$n){[$b,$f,$t]=explode('|',$k,3);$lines[]='| '.$b.' | '.$f.' | '.$t.' | '.$n.' |';}$lines[]='';$lines[]='## Question-level evidence';$lines[]='';$lines[]='| Question | Board | From | To | Topic | Concept | Existing question stem |';$lines[]='|---:|---|---|---|---|---|---|';foreach($rows as $r)$lines[]='| '.$r['question_id'].' | '.$r['board_id'].' | '.$r['from_subject_id'].' | '.$r['to_subject_id'].' | '.$r['topic_id'].' | '.$r['concept_id'].' | '.str_replace('|','\\|',$r['question_stem']).' |';$lines[]='';$lines[]='This report records taxonomy and blueprint evidence. Semantic cross-board reuse outside these direct corrections remains governed by existing reuse metadata and requires curriculum judgment.';$md=implode("\n",$lines)."\n";
foreach([[$opts['json'],$json],[$opts['markdown'],$md]] as [$path,$contents]){if(!is_dir(dirname($path)))mkdir(dirname($path),0755,true);file_put_contents($path.'.tmp',$contents,LOCK_EX);if(!rename($path.'.tmp',$path))throw new RuntimeException('Unable to write '.$path);}
printf("RECLASSIFIED=%d\nJSON=%s\nMARKDOWN=%s\n",count($rows),$opts['json'],$opts['markdown']);
